    39	extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    40	{
    41	  AspellCanHaveError *possible_err = NULL;
    42	  AspellSpeller *spell_checker = NULL;
    43	  AspellConfig *spell_config = NULL;
    44	  AspellDocumentChecker *doc_checker = NULL;
    45	  AspellCanHaveError *doc_err = NULL;
    46	  AspellToken token;
    47	  const char *data_str = reinterpret_cast<const char *>(data);
    48	  uint8_t config[MAX_CONFIG_LEN];
    49	  size_t config_len;
    50	  int rc;
    51	
    52	  // Enable or disable diagnostics based on the FUZZ_VERBOSE environment flag.
    53	  enable_diags = (getenv("FUZZ_VERBOSE") != NULL);
    54	
    55	  // Copy up to MAX_CONFIG_LEN bytes from the data.
    56	  config_len = std::min(size, MAX_CONFIG_LEN);
    57	  memcpy(config, data, config_len);
    58	
    59	  // Create a new configuration class.
    60	  spell_config = new_aspell_config();
    61	
    62	  // Parse configuration. Exit if the configuration was bad.
    63	  rc = parse_config(spell_config, config, config_len);
    64	  if (rc == -1)
    65	  {
    66	    FUZZ_DEBUG("Configuration parsing failed");
    67	    goto EXIT_LABEL;
    68	  }
    69	
    70	  // Move the data pointer past the config.
    71	  data_str += rc;
    72	  size -= rc;
    73	
    74	  FUZZ_DEBUG("Document: %.*s", (int)size, data_str);
    75	
    76	  // Replace the data dir with the relative directory so that it works wherever
    77	  // it is run from, so long as dictionary files are installed relative to it.
    78	  FUZZ_DEBUG("Overriding data-dir to %s", data_dir);
    79	  aspell_config_replace(spell_config, "data-dir", data_dir);
    80	
    81	  // Convert the configuration to a spell checker.
    82	  possible_err = new_aspell_speller(spell_config);
    83	  if (aspell_error_number(possible_err) != 0) {
    84	    // Failed on configuration.
    85	    FUZZ_DEBUG("Failed to create speller: %s",
    86	               aspell_error_message(possible_err));
    87	    delete_aspell_can_have_error(possible_err);
    88	    goto EXIT_LABEL;
    89	  }
    90	
    91	  // Create a spell checker.
    92	  spell_checker = to_aspell_speller(possible_err);
    93	
    94	  // Convert the spell checker to a document checker.
    95	  doc_err = new_aspell_document_checker(spell_checker);
    96	  if (aspell_error(doc_err) != 0) {
    97	    // Failed to convert to a document checker.
    98	    FUZZ_DEBUG("Failed to create document checker: %s",
    99	               aspell_error_message(doc_err));
   100	    delete_aspell_can_have_error(doc_err);
   101	    goto EXIT_LABEL;
   102	  }
   103	
   104	  doc_checker = to_aspell_document_checker(doc_err);
   105	
   106	  // Process the remainder of the document.
   107	  aspell_document_checker_process(doc_checker, data_str, size);
   108	
   109	  // Iterate over all misspellings.
   110	  token = aspell_document_checker_next_misspelling(doc_checker);
   111	
   112	  FUZZ_DEBUG("Token len %d", token.len);
   113	
   114	  for (;
   115	       token.len != 0;
   116	       token = aspell_document_checker_next_misspelling(doc_checker))
   117	  {
   118	    // Get spelling suggestions for the misspelling.
   119	    auto word_list = aspell_speller_suggest(spell_checker,
   120	                                            data_str + token.offset,
   121	                                            token.len);
   122	
   123	    // Iterate over the suggested replacement words in the word list.
   124	    AspellStringEnumeration *els = aspell_word_list_elements(word_list);
   125	
   126	    for (const char *word = aspell_string_enumeration_next(els);
   127	         word != 0;
   128	         word = aspell_string_enumeration_next(els))
   129	    {
   130	      // Conditionally print out the suggested replacement words.
   131	      FUZZ_DEBUG("Suggesting replacement for word at offset %d len %d: %s",
   132	                 token.offset,
   133	                 token.len,
   134	                 word);
   135	    }
   136	    delete_aspell_string_enumeration(els);
   137	  }
